 JsonNode getAs(String c,String label,String path,User who,int expected)throws Exception{var req=get(path);if(who!=null)req.cookie(auth(who));return perform(c,label,req,expected);}
 JsonNode patchAs(String c,String label,String path,User who,Object body,int expected)throws Exception{var req=patch(path);if(who!=null)req=mutation(req,who);else req.cookie(new Cookie("XSRF-TOKEN","qa-isolated-csrf")).header("X-XSRF-TOKEN","qa-isolated-csrf").contentType(MediaType.APPLICATION_JSON);req.content(body instanceof String?(String)body:mapper.writeValueAsString(body));JsonNode response=perform(c,label,req,expected);if(expected!=200)return response;JsonNode persisted=getAs(c,label+"-persisted-readback",path,who,200);ObjectNode a=response.deepCopy(),b=persisted.deepCopy();a.remove("updatedAt");b.remove("updatedAt");assertEquals(a,b);return persisted;}
