class CatalogProductDeletionReferenceTest extends CatalogProductOwnershipPublicationTest {
 @Autowired StorefrontConfigRepository storefronts;
 @Autowired ProductLandingPageConfigRepository landings;
 @Autowired MembershipFeedEntryRepository feeds;
 @Autowired MembershipContentRepository nativeContent;
 @Autowired MembershipProductRepository memberships;
 static JdbcTemplate lastJdbc;
 @BeforeEach void jdbcReference(){lastJdbc=jdbc;jdbc.execute("ALTER TABLE storefront_product_order ADD CONSTRAINT uk_storefront_product UNIQUE(storefront_config_id,product_id)");jdbc.execute("ALTER TABLE product_landing_section_order ADD CONSTRAINT uk_landing_order_section UNIQUE(config_id,section_id)");}
 @AfterEach void cleanupReferences(){jdbc.execute("ALTER TABLE storefront_product_order DROP CONSTRAINT IF EXISTS uk_storefront_product");jdbc.execute("ALTER TABLE product_landing_section_order DROP CONSTRAINT IF EXISTS uk_landing_order_section");storefronts.deleteAll();landings.deleteAll();feeds.deleteAll();nativeContent.deleteAll();files.deleteAll();fileSections.deleteAll();}
 @AfterAll static void verifyTables(){for(String t:List.of("storefront_configs","storefront_product_order","product_landing_page_configs","product_landing_visible_sections","product_landing_section_order","membership_content","membership_feed_entries","files_download_products","sections_download_products","course_products","download_products","consultation_products","membership_products","users","roles","product_entitlements","admin_audit_logs"))assertEquals(0L,lastJdbc.queryForObject("select count(*) from "+t,Long.class),t);observations.add(Map.of("case_id","CLEANUP","tables_empty",true,"external_services","unused by inherited verification"));}
 @Override JsonNode perform(String cid,String label,MockHttpServletRequestBuilder req,int expected)throws Exception{var result=mvc.perform(req).andReturn();var response=result.getResponse();String txt=response.getContentAsString();JsonNode n;if(txt.isEmpty())n=mapper.nullNode();else if(response.getContentType()!=null&&response.getContentType().contains("json"))n=mapper.readTree(txt);else n=mapper.getNodeFactory().textNode(txt);observations.add(Map.of("case_id",cid,"label",label,"actual_status",response.getStatus(),"expected_status",expected,"response_kind",n.isTextual()?"text":n.isNull()?"empty":"json","observed_at",Instant.now().toString()));assertEquals(expected,response.getStatus(),cid+" "+label);return n;}
 String membershipPath(Product m){return "/api/products/"+m.getId()+"/membership";}
 JsonNode postContent(String cid,String label,Product m,User caller)throws Exception{return perform(cid,label,mutation(post(membershipPath(m)+"/content"),caller).content("{\"type\":\"POST\",\"title\":\"QA retained native post\",\"status\":\"DRAFT\",\"body\":\"<p>Synthetic isolated body</p>\"}"),201);}
 JsonNode feed(String cid,String label,Product m,User caller,List<Map<String,Object>> rows)throws Exception{return perform(cid,label,mutation(put(membershipPath(m)+"/feed"),caller).content(mapper.writeValueAsString(Map.of("orderingMode","MANUAL","feed",rows))),200);}
 JsonNode aggregate(String cid,String label,Product m,User caller,int status)throws Exception{return perform(cid,label,get(membershipPath(m)).cookie(auth(caller)),status);}
 void presentation(Product p,User creator,Product kept){StorefrontConfig store=new StorefrontConfig();store.setCreator(creator);store.setFeaturedProductId(p.getId());store.setProductOrderIds(new ArrayList<>(List.of(p.getId(),kept.getId())));storefronts.saveAndFlush(store);ProductLandingPageConfig landing=new ProductLandingPageConfig();landing.setProductId(p.getId());landing.setMarketingDescription("QA disposable landing");landing.setVisibleSections(new ArrayList<>(List.of(ProductLandingSection.ABOUT,ProductLandingSection.CONTENTS,ProductLandingSection.CREATOR)));landing.setSectionOrder(new ArrayList<>(List.of(ProductLandingSection.ABOUT,ProductLandingSection.CONTENTS,ProductLandingSection.CREATOR)));landings.saveAndFlush(landing);}
 record Links(Product membership,Product underlying,UUID nativeId,Set<UUID> sectionIds,Set<UUID> lessonIds,Set<UUID> fileIds){}
 Links childAndFeed(String cid,Product p,User creator,Product kept)throws Exception{
  Set<UUID> ss=new HashSet<>(),ls=new HashSet<>(),fs=new HashSet<>();Product m=null,underlying=null;UUID nativeId=null;
  if(p.getType()==ProductType.COURSE){courseContent(p);for(CourseSection s:sections.findAll())if(s.getCourse().getId().equals(p.getId())){ss.add(s.getId());for(CourseLesson l:lessons.findAll())if(l.getSection().getId().equals(s.getId()))ls.add(l.getId());}}
  if(p.getType()==ProductType.DOWNLOAD){FileDownloadProduct f=downloadFile(p);ss.add(f.getSection().getId());fs.add(f.getId());}
  if(p.getType()==ProductType.MEMBERSHIP){m=p;underlying=seed(ProductType.DOWNLOAD,creator,"0",ProductStatus.HIDDEN);}else if(p.getType()==ProductType.COURSE||p.getType()==ProductType.DOWNLOAD)m=seed(ProductType.MEMBERSHIP,creator,"3",ProductStatus.DRAFT);
  if(m!=null){JsonNode post=postContent(cid,"native-post-fixture",m,creator);nativeId=UUID.fromString(post.path("id").asText());List<Map<String,Object>> entries=new ArrayList<>();entries.add(Map.of("kind","CONTENT","contentId",nativeId));entries.add(Map.of("kind","PRODUCT","productId",kept.getId()));entries.add(Map.of("kind","PRODUCT","productId",p.getType()==ProductType.MEMBERSHIP?underlying.getId():p.getId()));JsonNode a=feed(cid,"feed-fixture",m,creator,entries);assertEquals(3,a.path("feed").size());assertEquals(1,a.path("content").size());}
  return new Links(m,underlying,nativeId,ss,ls,fs);
 }
 void deletionMatrix(String cid,boolean legacy)throws Exception{
  for(boolean useAdmin:List.of(false,true))for(ProductType type:ProductType.values())for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){
   User creator=extra(cid+"-"+type+"-"+state+"-"+useAdmin,owner);User actor=useAdmin?admin:creator;String label=(useAdmin?"Admin":"owner")+"-"+type+"-"+state;Product p=seed(type,creator,"8",state),kept=seed(ProductType.COURSE,creator,"0",ProductStatus.PUBLISHED);String keptName=kept.getName();Links links=childAndFeed(cid,p,creator,kept);presentation(p,creator,kept);
   grant(p,buyer,EntitlementSource.ADMIN_GRANT,EntitlementStatus.ACTIVE);grant(p,creator,EntitlementSource.FREE_ENROLLMENT,EntitlementStatus.REVOKED);grant(kept,buyer,EntitlementSource.ADMIN_GRANT,EntitlementStatus.ACTIVE);long grantBefore=grants.count(),auditsBefore=audits.count();
   JsonNode before=perform(cid,label+"-owner-product-before",get("/api/products/"+p.getId()).cookie(auth(creator)),200);assertEquals(creator.getUserId().toString(),before.path("userId").asText());
   MockHttpServletRequestBuilder request=legacy?mutation(delete("/api/products"),actor).param("userId",actor.getUserId().toString()).param("productType",type.name()).param("id",p.getId().toString()):mutation(delete("/api/products/"+p.getId()),actor);
   JsonNode deleted=perform(cid,label+"-delete",request,legacy?202:204);if(legacy)assertEquals("Product deleted succesfully: "+p.getId(),deleted.asText());else assertTrue(deleted.isNull());
   perform(cid,label+"-missing-product",get("/api/products/"+p.getId()).cookie(auth(creator)),404);perform(cid,label+"-missing-landing",get("/api/creator/products/"+p.getId()+"/landing-page").cookie(auth(creator)),404);assertFalse(products.existsById(p.getId()));assertTrue(landings.findByProductId(p.getId()).isEmpty());assertEquals(grantBefore-2,grants.count());
   JsonNode library=perform(cid,label+"-library-after",get("/api/entitlements/me").cookie(auth(buyer)),200);Set<String> ids=new HashSet<>();for(JsonNode e:library)ids.add(e.path("product").path("id").asText());assertFalse(ids.contains(p.getId().toString()));assertTrue(ids.contains(kept.getId().toString()));
   JsonNode config=perform(cid,label+"-store-config-after",get("/api/creator/storefront").cookie(auth(creator)),200);assertTrue(config.path("featuredProductId").isNull());assertEquals(mapper.valueToTree(List.of(kept.getId())),config.path("productOrderIds"));JsonNode publicStore=perform(cid,label+"-public-store-after",get("/api/storefronts/"+creator.getUserId()),200);assertEquals(1,publicStore.path("products").size());assertEquals(kept.getId().toString(),publicStore.path("products").get(0).path("id").asText());assertTrue(publicStore.path("featuredProductId").isNull());
   JsonNode retained=perform(cid,label+"-kept-product-after",get("/api/products/"+kept.getId()).cookie(auth(creator)),200);assertEquals(keptName,retained.path("name").asText());assertEquals(creator.getUserId().toString(),retained.path("userId").asText());
   if(links.membership()!=null){if(type==ProductType.MEMBERSHIP){aggregate(cid,label+"-deleted-membership",p,creator,404);assertTrue(nativeContent.findById(links.nativeId()).isEmpty());assertTrue(feeds.findAllByMembershipId(p.getId()).isEmpty());perform(cid,label+"-included-download-retained",get("/api/products/"+links.underlying().getId()).cookie(auth(creator)),200);}else{JsonNode a=aggregate(cid,label+"-remaining-membership",links.membership(),creator,200);assertEquals(2,a.path("feed").size());assertEquals(1,a.path("content").size());assertEquals(links.nativeId().toString(),a.path("content").get(0).path("id").asText());assertFalse(a.toString().contains(p.getId().toString()));assertTrue(a.toString().contains(kept.getId().toString()));}}
   for(UUID id:links.sectionIds())assertFalse(type==ProductType.COURSE?sections.existsById(id):fileSections.existsById(id));for(UUID id:links.lessonIds())assertFalse(lessons.existsById(id));for(UUID id:links.fileIds())assertFalse(files.existsById(id));
   assertEquals(auditsBefore+(useAdmin?1:0),audits.count());if(useAdmin){var audit=audits.findAll().stream().filter(a->a.getAction().equals("PRODUCT_DELETE")&&a.getTargetId().equals(p.getId().toString())).findFirst().orElseThrow();assertEquals(admin.getUserId(),audit.getActorUserId());assertTrue(audit.getBeforeSummary().contains(creator.getUserId().toString()));assertEquals("ownerId="+creator.getUserId(),audit.getAfterSummary());}
  }
  assertEquals(0,orders.count());assertEquals(0,attempts.count());assertEquals(0,events.count());
 }
 @Test void papi014CanonicalCompleteReferenceCleanup()throws Exception{deletionMatrix("PAPI-014",false);}
 @Test void papi015LegacyCompleteReferenceCleanup()throws Exception{deletionMatrix("PAPI-015",true);}
 @Test void papi015LegacyAuthorizationAndInvalidInputsAtomic()throws Exception{
  User foreign=extra("legacy-delete-nonowner",owner);
  for(ProductType type:ProductType.values()){
   User creator=extra("legacy-guard-owner-"+type,owner);Product p=seed(type,creator,"8",ProductStatus.DRAFT),kept=seed(ProductType.COURSE,creator,"0",ProductStatus.PUBLISHED);presentation(p,creator,kept);grant(p,buyer,EntitlementSource.ADMIN_GRANT,EntitlementStatus.ACTIVE);JsonNode original=read("PAPI-015",type+"-before-denials",p,creator);long grantCount=grants.count(),auditCount=audits.count();
   for(User caller:Arrays.asList(null,buyer,foreign)){MockHttpServletRequestBuilder request=delete("/api/products").param("userId",creator.getUserId().toString()).param("productType",type.name()).param("id",p.getId().toString());String label=caller==null?"Guest":caller==buyer?"User":"foreign-Creator";if(caller==null)request.cookie(new jakarta.servlet.http.Cookie("XSRF-TOKEN","qa-isolated-csrf")).header("X-XSRF-TOKEN","qa-isolated-csrf");else request=mutation(request,caller);perform("PAPI-015",type+"-forged-owner-query-"+label,request,caller==null?401:403);assertEquals(original,read("PAPI-015",type+"-unchanged-after-"+label,p,creator));assertEquals(grantCount,grants.count());assertEquals(auditCount,audits.count());assertTrue(landings.findByProductId(p.getId()).isPresent());JsonNode config=perform("PAPI-015",type+"-config-retained-after-"+label,get("/api/creator/storefront").cookie(auth(creator)),200);assertEquals(p.getId().toString(),config.path("featuredProductId").asText());assertEquals(mapper.valueToTree(List.of(p.getId(),kept.getId())),config.path("productOrderIds"));}
   for(String badType:List.of("UNSUPPORTED",type==ProductType.COURSE?"DOWNLOAD":"COURSE")){perform("PAPI-015",type+"-bad-type-"+badType,mutation(delete("/api/products"),creator).param("userId",creator.getUserId().toString()).param("productType",badType).param("id",p.getId().toString()),badType.equals("UNSUPPORTED")?400:404);assertEquals(original,read("PAPI-015",type+"-bad-type-rollback",p,creator));assertEquals(grantCount,grants.count());assertTrue(landings.findByProductId(p.getId()).isPresent());}
  }
  for(String id:List.of(UUID.randomUUID().toString(),"not-a-uuid"))perform("PAPI-015","missing-or-malformed-id",mutation(delete("/api/products"),owner).param("userId",owner.getUserId().toString()).param("productType","COURSE").param("id",id),id.equals("not-a-uuid")?400:404);
  noFinancialRecordsExceptGrants();
 }
 void noFinancialRecordsExceptGrants(){assertEquals(0,orders.count());assertEquals(0,attempts.count());assertEquals(0,events.count());}
 @Test void papi006AdminSharedAndTypeAuthoring()throws Exception{
  for(ProductType type:ProductType.values()){Product p=seed(type,owner,"8",ProductStatus.DRAFT);long auditBefore=audits.count();JsonNode updated=patchBody("PAPI-006",type+"-Admin-shared-patch",p,admin,Map.of("name","QA Admin updated "+type,"description","QA Admin persisted description"),200);assertEquals(owner.getUserId().toString(),updated.path("userId").asText());JsonNode saved=read("PAPI-006",type+"-owner-read",p,owner);assertEquals("QA Admin updated "+type,saved.path("name").asText());assertEquals("QA Admin persisted description",saved.path("description").asText());assertEquals(auditBefore+1,audits.count());var audit=audits.findAll().stream().filter(a->a.getTargetId().equals(p.getId().toString())).findFirst().orElseThrow();assertEquals(admin.getUserId(),audit.getActorUserId());assertEquals("PRODUCT_UPDATE",audit.getAction());assertTrue(audit.getBeforeSummary().contains(p.getName()));assertTrue(audit.getAfterSummary().contains("QA Admin updated "+type));
