Text().toLowerCase();Map<String,Object>obs=new LinkedHashMap<>();obs.put("case_id",c);obs.put("label",role(caller)+state+"-repair-existing-Monday");obs.put("actual_status",status);obs.put("expected_status",200);obs.put("availability_unique_constraint_error",msg.contains("unique")&&msg.contains("consultation_availability_days"));obs.put("observed_at",java.time.Instant.now().toString());observations.add(obs);if(status!=200){unexpectedRepairs++;assertEquals(400,status);assertTrue((Boolean)obs.get("availability_unique_constraint_error"));assertEquals(before,read(c,role(caller)+state+"-repair-rollback",p,owner));patchBody(c,role(caller)+state+"-clear-availability-control",p,caller,Map.of("details",Map.of("weeklyAvailability",List.of())),200);acceptedPublication(c,p,caller,fix);}else acceptedPublication(c,p,caller,Map.of());}else acceptedPublication(c,p,caller,fix);}assertEquals(0,unexpectedRepairs,c+" existing weekday corrected in one PATCH must save and publish");}
