package com.myproject.video.video_platform.controller.commerce;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.myproject.video.video_platform.common.enums.products.*;
import com.myproject.video.video_platform.common.enums.entitlement.*;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.repository.products.membership.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import org.junit.jupiter.api.*;
import jakarta.servlet.http.Cookie;
import java.util.*;
import java.math.BigInteger;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

class CatalogMembershipContractTest extends CatalogProductOwnershipPublicationTest {
 @Autowired MembershipContentRepository contents;
 @Autowired MembershipFeedEntryRepository feedEntries;
 static JdbcTemplate lastJdbc;
 @BeforeEach void rememberJdbc(){lastJdbc=jdbc;}
 @AfterEach void nativeCleanup(){feedEntries.deleteAll();contents.deleteAll();}
 @AfterAll static void assertCleanup(){for(String table:List.of("membership_content","membership_feed_entries","membership_products","course_products","download_products","consultation_products","product_entitlements","users","roles","admin_audit_logs","commerce_orders","commerce_payment_attempts","commerce_payment_events"))assertEquals(0L,lastJdbc.queryForObject("select count(*) from "+table,Long.class),table);observations.add(Map.of("case_id","CLEANUP","tables_empty",true,"external_services","unused by inherited verification"));}
 Product membership(ProductStatus state){return seed(ProductType.MEMBERSHIP,owner,"7.50",state);}
 String path(Product m){return "/api/products/"+m.getId()+"/membership";}
 JsonNode aggregate(String c,String label,Product m,User u,int expected)throws Exception{var b=get(path(m));if(u!=null)b.cookie(auth(u));return perform(c,label,b,expected);}
 MockHttpServletRequestBuilder mut(MockHttpServletRequestBuilder b,User u){return u==null?b.cookie(new Cookie("XSRF-TOKEN","qa-isolated-csrf")).header("X-XSRF-TOKEN","qa-isolated-csrf").contentType("application/json"):mutation(b,u);}
 ObjectNode asset(String type){ObjectNode n=mapper.createObjectNode();n.put("fileName",type.equals("VIDEO")?"qa.mp4":"qa.pdf");n.put("fileType",type.equals("VIDEO")?"video/mp4":"application/pdf");n.put("size",1);return n;}
 String assetField(String type){return type.equals("VIDEO")?"video":"file";}
 ObjectNode content(String type){ObjectNode n=mapper.createObjectNode();n.put("type",type);n.put("title"," QA native "+type+" ");n.put("description","QA optional description");n.put("status","DRAFT");if(type.equals("POST"))n.put("body"," <p>QA body</p> ");else n.set(assetField(type),asset(type));return n;}
 JsonNode createNative(String c,String label,Product m,User u,JsonNode body,int status)throws Exception{return perform(c,label,mut(post(path(m)+"/content"),u).content(body.toString()),status);}
 JsonNode patchNative(String c,String label,Product m,String id,User u,JsonNode body,int status)throws Exception{return perform(c,label,mut(patch(path(m)+"/content/"+id),u).content(body.toString()),status);}
 JsonNode savedContent(JsonNode aggregate,String id){for(JsonNode n:aggregate.path("content"))if(n.path("id").asText().equals(id))return n;throw new AssertionError("Saved content missing");}
 void rejectedCreate(String cid,String label,Product m,User caller,ObjectNode n,int status)throws Exception{JsonNode before=aggregate(cid,label+"-before",m,owner,200);long c=contents.count(),f=feedEntries.count();createNative(cid,label,m,caller,n,status);assertEquals(before,aggregate(cid,label+"-unchanged",m,owner,200));assertEquals(c,contents.count());assertEquals(f,feedEntries.count());}
 ObjectNode feedBody(String ordering,List<Map<String,Object>> entries){ObjectNode n=mapper.createObjectNode();n.put("orderingMode",ordering);n.set("feed",mapper.valueToTree(entries));return n;}
 JsonNode putFeed(String cid,String label,Product m,User caller,JsonNode n,int status)throws Exception{return perform(cid,label,mut(put(path(m)+"/feed"),caller).content(n.toString()),status);}
 @Test void mem006MetadataBoundaryAndAtomicRejection()throws Exception{
  for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){
   Product m=membership(state);String prefix=role(caller)+"-"+state;
   for(String type:List.of("POST","VIDEO","RESOURCE")){
    ObjectNode good=content(type);good.put("title","  "+"T".repeat(255)+"  ");if(!type.equals("POST")){ObjectNode a=(ObjectNode)good.path(assetField(type));a.put("fileName","  "+"F".repeat(255)+"  ");a.put("fileType","  "+"M".repeat(150)+"  ");a.put("size",536870912L);}
    JsonNode saved=createNative("MEM-006",prefix+"-"+type+"-max-valid",m,caller,good,201);assertEquals("T".repeat(255),saved.path("title").asText());if(!type.equals("POST")){assertEquals(255,saved.path(assetField(type)).path("fileName").asText().length());assertEquals(150,saved.path(assetField(type)).path("fileType").asText().length());assertEquals(536870912L,saved.path(assetField(type)).path("size").asLong());UUID.fromString(saved.path(assetField(type)).path("fileId").asText());}
    for(String v:List.of("title256","blank-title","null-title","numeric-title")){ObjectNode n=content(type);switch(v){case"title256"->n.put("title","T".repeat(256));case"blank-title"->n.put("title","  ");case"null-title"->n.putNull("title");default->n.put("title",1);}rejectedCreate("MEM-006",prefix+"-"+type+"-"+v,m,caller,n,400);}
    if(type.equals("POST")){for(String value:List.of("","   ")){ObjectNode n=content(type);n.put("body",value);rejectedCreate("MEM-006",prefix+"-POST-blank-body",m,caller,n,400);}continue;}
    JsonNode minimum=createNative("MEM-006",prefix+"-"+type+"-size1",m,caller,content(type),201);assertEquals(1,minimum.path(assetField(type)).path("size").asLong());
    for(String v:List.of("filename256","mime151","size0","size-negative","size-max-plus1","size-fractional","size-string","size-over-long","missing-filename","missing-mime","missing-size","blank-filename","blank-mime","null-asset")){ObjectNode n=content(type);ObjectNode a=(ObjectNode)n.path(assetField(type));switch(v){case"filename256"->a.put("fileName","F".repeat(256));case"mime151"->a.put("fileType","M".repeat(151));case"size0"->a.put("size",0);case"size-negative"->a.put("size",-1);case"size-max-plus1"->a.put("size",536870913L);case"size-fractional"->a.put("size",1.5);case"size-string"->a.put("size","1");case"size-over-long"->a.put("size",new BigInteger("9223372036854775808"));case"missing-filename"->a.remove("fileName");case"missing-mime"->a.remove("fileType");case"missing-size"->a.remove("size");case"blank-filename"->a.put("fileName"," ");case"blank-mime"->a.put("fileType"," ");default->n.putNull(assetField(type));}rejectedCreate("MEM-006",prefix+"-"+type+"-"+v,m,caller,n,400);}
   }
  }noFinancialRecords();
 }
 @Test void mem008StatusAndFieldPatchesAcrossNativeKinds()throws Exception{for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Product m=membership(state);for(String type:List.of("POST","VIDEO","RESOURCE")){JsonNode n=createNative("MEM-008",role(caller)+state+type+"-create",m,caller,content(type),201);String id=n.path("id").asText();String fileId=type.equals("POST")?null:n.path(assetField(type)).path("fileId").asText();for(String status:List.of("PUBLISHED","HIDDEN","DRAFT")){ObjectNode b=mapper.createObjectNode();b.put("status",status);b.put("title"," QA edited "+type+" ");b.putNull("description");if(type.equals("POST"))b.put("body"," <p>QA edited body</p> ");JsonNode changed=patchNative("MEM-008",role(caller)+state+type+"-"+status,m,id,caller,b,200);assertEquals(id,changed.path("id").asText());assertEquals(status,changed.path("status").asText());assertEquals("QA edited "+type,changed.path("title").asText());assertTrue(changed.path("description").isNull()||changed.path("description").isMissingNode());JsonNode saved=savedContent(aggregate("MEM-008",type+status+"-readback",m,owner,200),id);assertEquals(status,saved.path("status").asText());assertEquals("QA edited "+type,saved.path("title").asText());if(type.equals("POST"))assertEquals("<p>QA edited body</p>",saved.path("body").asText());else assertEquals(fileId,saved.path(assetField(type)).path("fileId").asText());assertEquals(state,products.findById(m.getId()).orElseThrow().getStatus());}
   JsonNode before=aggregate("MEM-008",type+"-invalid-before",m,owner,200);if(type.equals("POST")){ObjectNode b=mapper.createObjectNode();b.put("body","");patchNative("MEM-008","blank-Post-body",m,id,caller,b,400);assertEquals(before,aggregate("MEM-008","invalid-body-unchanged",m,owner,200));}ObjectNode bad=mapper.createObjectNode();bad.put("status","UNKNOWN");patchNative("MEM-008",type+"-invalid-status",m,id,caller,bad,400);assertEquals(before,aggregate("MEM-008",type+"-status-unchanged",m,owner,200));}}
 }
 @Test void mem009ImmutableTypeAndServerAssetIdentity()throws Exception{for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Product m=membership(state);for(String type:List.of("POST","VIDEO","RESOURCE")){ObjectNode create=content(type);String forged=UUID.randomUUID().toString();if(!type.equals("POST"))((ObjectNode)create.path(assetField(type))).put("fileId",forged);JsonNode n=createNative("MEM-009",role(caller)+state+type+"-create",m,caller,create,201);String id=n.path("id").asText();JsonNode before=aggregate("MEM-009",type+"-before-type-change",m,owner,200);ObjectNode bad=mapper.createObjectNode();bad.put("type",type.equals("POST")?"VIDEO":"POST");patchNative("MEM-009",type+"-type-change",m,id,caller,bad,409);assertEquals(before,aggregate("MEM-009",type+"-type-rejection-unchanged",m,owner,200));if(type.equals("POST"))continue;String field=assetField(type),original=n.path(field).path("fileId").asText();assertNotEquals(forged,original);UUID.fromString(original);ObjectNode same=mapper.createObjectNode();same.set(field,n.path(field).deepCopy());JsonNode unchanged=patchNative("MEM-009",type+"-matching-identity",m,id,caller,same,200);assertEquals(original,unchanged.path(field).path("fileId").asText());((ObjectNode)same.path(field)).put("fileId",forged);JsonNode forgedPatch=patchNative("MEM-009",type+"-forged-identity",m,id,caller,same,200);String next=forgedPatch.path(field).path("fileId").asText();assertNotEquals(forged,next);assertNotEquals(original,next);UUID.fromString(next);ObjectNode replace=mapper.createObjectNode();ObjectNode changed=(ObjectNode)forgedPatch.path(field).deepCopy();changed.put("fileName","qa-replaced."+(type.equals("VIDEO")?"mp4":"pdf"));changed.put("size",20);replace.set(field,changed);JsonNode replaced=patchNative("MEM-009",type+"-changed-metadata",m,id,caller,replace,200);String finalId=replaced.path(field).path("fileId").asText();assertNotEquals(next,finalId);assertEquals(changed.path("fileName"),replaced.path(field).path("fileName"));assertEquals(20,replaced.path(field).path("size").asLong());JsonNode saved=savedContent(aggregate("MEM-009",type+"-committed-asset",m,owner,200),id);assertEquals(finalId,saved.path(field).path("fileId").asText());assertEquals(id,saved.path("id").asText());}}
 }
 @Test void mem010PartialAssetRejectsWithoutMutation()throws Exception{for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Product m=membership(state);for(String type:List.of("VIDEO","RESOURCE")){JsonNode n=createNative("MEM-010",role(caller)+state+type+"-create",m,caller,content(type),201);String id=n.path("id").asText();JsonNode before=aggregate("MEM-010",type+"-before",m,owner,200);for(String field:List.of("fileName","fileType","size","fileId")){ObjectNode patch=mapper.createObjectNode(),a=mapper.createObjectNode();if(field.equals("size"))a.put(field,2);else a.put(field,field.equals("fileId")?UUID.randomUUID().toString():"QA partial");patch.set(assetField(type),a);patchNative("MEM-010",type+"-only-"+field,m,id,caller,patch,400);assertEquals(before,aggregate("MEM-010",type+"-unchanged-"+field,m,owner,200));}}}
 }
 @Test void mem014ExactNativeSetAndIncludedOwnership()throws Exception{User foreign=extra("membership-foreign-owner",owner);for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Product m=membership(state);List<Map<String,Object>> base=new ArrayList<>();for(String type:List.of("POST","VIDEO","RESOURCE")){JsonNode n=createNative("MEM-014",role(caller)+state+type+"-fixture",m,caller,content(type),201);base.add(Map.of("kind","CONTENT","contentId",n.path("id").asText()));}List<Product> owned=new ArrayList<>();for(ProductType type:List.of(ProductType.COURSE,ProductType.DOWNLOAD))for(ProductStatus status:ProductStatus.values()){Product p=seed(type,owner,"1",status);owned.add(p);base.add(Map.of("kind","PRODUCT","productId",p.getId()));}putFeed("MEM-014","valid-six-inclusions",m,caller,feedBody("MANUAL",base),200);JsonNode before=aggregate("MEM-014","baseline",m,owner,200);List<List<Map<String,Object>>> bad=new ArrayList<>();List<Map<String,Object>> omitted=new ArrayList<>(base);omitted.remove(0);bad.add(omitted);List<Map<String,Object>> duplicateNative=new ArrayList<>(base);duplicateNative.add(base.get(0));bad.add(duplicateNative);List<Map<String,Object>> duplicateProduct=new ArrayList<>(base);duplicateProduct.add(base.get(3));bad.add(duplicateProduct);for(Product p:List.of(seed(ProductType.COURSE,foreign,"1",ProductStatus.DRAFT),seed(ProductType.DOWNLOAD,foreign,"1",ProductStatus.PUBLISHED),seed(ProductType.CONSULTATION,owner,"1",ProductStatus.DRAFT),seed(ProductType.MEMBERSHIP,owner,"1",ProductStatus.DRAFT))){List<Map<String,Object>> list=new ArrayList<>(base);list.add(Map.of("kind","PRODUCT","productId",p.getId()));bad.add(list);}List<Map<String,Object>> missing=new ArrayList<>(base);missing.add(Map.of("kind","PRODUCT","productId",UUID.randomUUID()));bad.add(missing);for(int i=0;i<bad.size();i++){putFeed("MEM-014",role(caller)+state+"-invalid-feed-"+i,m,caller,feedBody("MANUAL",bad.get(i)),409);assertEquals(before,aggregate("MEM-014","rejected-feed-unchanged-"+i,m,owner,200));}assertEquals(9,before.path("feed").size());for(Product p:owned)assertTrue(products.existsById(p.getId()));assertEquals(0,grants.count());}
