 Map<UUID,Set<String>> rolesNow(){Map<UUID,Set<String>> n=new HashMap<>();for(User u:users.findAll()){Set<String> r=new HashSet<>();u.getRoles().forEach(x->r.add(x.getRoleName()));n.put(u.getUserId(),r);}return n;}
 JsonNode rolePatch(String c,String label,String id,User actor,String body,int expected)throws Exception{return perform(c,label,mutation(patch("/api/admin/users/"+id+"/role"),actor).content(body),expected);}
 @Test void admin006InvalidTargetsAndPayloadsAtomic()throws Exception{
  Map<UUID,Set<String>> before=rolesNow();int i=0;
  for(String body:List.of("{}","{\"role\":null}","{\"role\":\"UNKNOWN\"}","{\"role\":\"\"}","{\"role\":17}","{\"role\":{}}","{\"role\":\"creator\"}")){
   rolePatch("ADMIN-006","invalid-body-"+i++,buyer.getUserId().toString(),admin,body,400);assertEquals(before,rolesNow());assertEquals(0,audits.count());
  }
  for(String id:List.of("not-a-uuid",UUID.randomUUID().toString())){rolePatch("ADMIN-006","invalid-target-"+id,id,admin,"{\"role\":\"CREATOR\"}",id.equals("not-a-uuid")?400:404);assertEquals(before,rolesNow());assertEquals(0,audits.count());}
  JsonNode success=rolePatch("ADMIN-006","valid-control",buyer.getUserId().toString(),admin,"{\"role\":\"CREATOR\"}",200);assertEquals(1,success.path("roles").size());assertEquals("CREATOR",success.path("roles").get(0).asText());assertEquals(Set.of("CREATOR"),rolesNow().get(buyer.getUserId()));assertEquals(before.get(owner.getUserId()),rolesNow().get(owner.getUserId()));assertEquals(before.get(admin.getUserId()),rolesNow().get(admin.getUserId()));assertEquals(1,audits.count());
 }
 @Test void admin013AllFourRoutesGateAndAdminControl()throws Exception{
  seed(ProductType.COURSE,owner,"10",ProductStatus.DRAFT);Map<UUID,Set<String>> before=rolesNow();
  for(User u:Arrays.asList(null,buyer,owner)){String r=u==null?"Guest":role(u);for(String route:List.of("users","products","audit")){var req=get("/api/admin/"+route);if(u!=null)req.cookie(auth(u));JsonNode n=perform("ADMIN-013",r+"-"+route,req,u==null?401:403);assertFalse(n.has("content"));assertFalse(n.toString().contains("buyer@example.com"));}
   var req=patch("/api/admin/users/"+buyer.getUserId()+"/role");if(u!=null)req=mutation(req,u);else req.contentType(org.springframework.http.MediaType.APPLICATION_JSON).cookie(new jakarta.servlet.http.Cookie("XSRF-TOKEN","qa-isolated-csrf")).header("X-XSRF-TOKEN","qa-isolated-csrf");perform("ADMIN-013",r+"-role-patch",req.content("{\"role\":\"CREATOR\"}"),u==null?401:403);assertEquals(before,rolesNow());assertEquals(0,audits.count());assertEquals(1,products.count());
  }
  for(String route:List.of("users","products","audit")){JsonNode n=perform("ADMIN-013","Admin-"+route,get("/api/admin/"+route).cookie(auth(admin)),200);assertTrue(n.path("content").isArray());assertEquals(route.equals("users")?3:route.equals("products")?1:0,n.path("totalElements").asInt());}
  rolePatch("ADMIN-013","Admin-role-patch",buyer.getUserId().toString(),admin,"{\"role\":\"CREATOR\"}",200);assertEquals(1,audits.count());JsonNode log=perform("ADMIN-013","Admin-audit-after-success",get("/api/admin/audit").cookie(auth(admin)),200);assertEquals(1,log.path("totalElements").asInt());assertEquals("ROLE_CHANGE",log.path("content").get(0).path("action").asText());
 }
 Set<String> ids(JsonNode page){Set<String> s=new HashSet<>();page.path("content").forEach(n->s.add(n.path("id").asText()));return s;}
 @Test void disc012OwnerSearchRoleLifecyclePaginationAndSort()throws Exception{
  User other=extra("SearchAuthorUnique",owner);owner.setFirstName("SearchAuthorUnique");users.saveAndFlush(owner);Map<UUID,Set<String>> expected=new HashMap<>();
  for(User creator:List.of(owner,other)){Set<String> set=new HashSet<>();for(ProductType t:ProductType.values())for(ProductStatus state:ProductStatus.values()){Product p=seed(t,creator,"10",state);p.setName("QA OwnerSearch "+t+" "+state);products.saveAndFlush(p);set.add(p.getId().toString());}Product x=seed(ProductType.COURSE,creator,"0",ProductStatus.DRAFT);x.setName("Unmatched product");products.saveAndFlush(x);expected.put(creator.getUserId(),set);}
  for(User actor:Arrays.asList(null,buyer,owner,admin))for(User creator:List.of(owner,other)){String label=(actor==null?"Guest":role(actor))+"-owner-"+(creator==owner?"A":"B");String url="/api/products/search/"+creator.getUserId()+"/products";
   for(String sort:List.of("name,asc","name,desc","createdAt,desc")){Set<String> collected=new HashSet<>();List<String> names=new ArrayList<>();for(int page=0;page<3;page++){var req=get(url).param("term","  qA oWnErSeArCh  ").param("page",""+page).param("size","5").param("sort",sort);if(actor!=null)req.cookie(auth(actor));JsonNode n=perform("DISC-012",label+"-"+sort+"-page-"+page,req,200);assertEquals(12,n.path("totalElements").asInt());assertEquals(3,n.path("totalPages").asInt());assertEquals(page,n.path("number").asInt());assertEquals(page<2?5:2,n.path("content").size());for(JsonNode item:n.path("content")){assertTrue(collected.add(item.path("id").asText()));assertEquals(creator.getUserId().toString(),products.findById(UUID.fromString(item.path("id").asText())).orElseThrow().getUser().getUserId().toString());names.add(item.path("name").asText());assertFalse(item.has("details"));} }assertEquals(expected.get(creator.getUserId()),collected);if(sort.startsWith("name")){List<String> sorted=new ArrayList<>(names);sorted.sort(sort.endsWith("asc")?Comparator.naturalOrder():Comparator.reverseOrder());assertEquals(sorted,names);}}
   var req=get(url).param("term","SearchAuthorUnique");if(actor!=null)req.cookie(auth(actor));assertEquals(0,perform("DISC-012",label+"-author-not-title",req,200).path("totalElements").asInt());
  }
  JsonNode global=perform("DISC-012","Guest-global-author-match",get("/api/products/search").param("term","SearchAuthorUnique").param("size","50"),200);assertEquals(26,global.path("totalElements").asInt());
  perform("DISC-012","unknown-owner",get("/api/products/search/"+UUID.randomUUID()+"/products").param("term",""),404);perform("DISC-012","malformed-owner",get("/api/products/search/not-a-uuid/products").param("term",""),400);perform("DISC-012","missing-term",get("/api/products/search/"+owner.getUserId()+"/products"),400);
  observations.add(Map.of("case_id","DISC-012","kind","summary-lifecycle-observation","all_roles_include_draft_hidden_published",true,"owner_isolation",true,"protected_body_returned",false));
 }
 Map<String,Object> initialDetails(){Map<String,Object>d=new LinkedHashMap<>();d.put("durationMinutes",30);d.put("meetingMethod","OTHER");d.put("customLocation","QA original location");d.put("bufferBeforeMinutes",5);d.put("bufferAfterMinutes",10);d.put("maxSessionsPerDay",4);d.put("confirmationMessage","QA original message");d.put("cancellationPolicy","FLEXIBLE");d.put("weeklyAvailability",List.of(availability(true,false)));return d;}
 @Test void cons005PartialUpdatesNullBlankAndInvalidDayRollback()throws Exception{
  for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){
   String label=role(caller)+"-"+state;Map<String,Object> b=payload(ProductType.CONSULTATION,owner);b.put("status",state.name());b.put("price","10");b.put("details",initialDetails());Product p=entity(create("CONS-005",label+"-create",caller,b,201));JsonNode before=read("CONS-005",label+"-initial",p,owner);
   JsonNode changed=patchBody("CONS-005",label+"-shared-name-only",p,caller,Map.of("name","QA changed shared name"),200);assertEquals(before.path("details"),changed.path("details"));
   JsonNode current=changed;for(var update:Map.<String,Object>of("durationMinutes",45,"meetingMethod","PHONE","customLocation","QA changed location","bufferBeforeMinutes",15,"bufferAfterMinutes",20,"maxSessionsPerDay",7,"confirmationMessage","QA changed message","cancellationPolicy","STRICT").entrySet()){JsonNode prior=current;current=patchBody("CONS-005",label+"-one-field-"+update.getKey(),p,caller,Map.of("details",Map.of(update.getKey(),update.getValue())),200);assertEquals(mapper.valueToTree(update.getValue()),current.path("details").path(update.getKey()));var fieldNames=prior.path("details").fieldNames();while(fieldNames.hasNext()){String field=fieldNames.next();if(!field.equals(update.getKey()))assertEquals(prior.path("details").path(field),current.path("details").path(field));}assertSameProduct(current,read("CONS-005",label+"-read-"+update.getKey(),p,owner));}
   Map<String,Object> nulls=new LinkedHashMap<>();for(String k:initialDetails().keySet())nulls.put(k,null);JsonNode nullUpdate=patchBody("CONS-005",label+"-explicit-null-preserves",p,caller,Map.of("details",nulls),200);assertEquals(current.path("details"),nullUpdate.path("details"));
   for(String k:List.of("customLocation","confirmationMessage","cancellationPolicy")){current=patchBody("CONS-005",label+"-clear-string-"+k,p,caller,Map.of("details",Map.of(k,"")),200);assertEquals("",current.path("details").path(k).asText());}
   for(String invalid:List.of("[{\"day\":\"BAD_DAY\",\"enabled\":true,\"windows\":[]}]","[{\"enabled\":true,\"windows\":[]}]","[null]","[{\"day\":\"MONDAY\",\"windows\":[]},{\"day\":\"MONDAY\",\"windows\":[]}]","[{\"day\":\"MONDAY\",\"windows\":[{\"startTime\":\"bad\",\"endTime\":\"10:00\"}]}]")){JsonNode stable=read("CONS-005",label+"-before-invalid-day",p,owner);perform("CONS-005",label+"-invalid-day-"+invalid.hashCode(),mutation(patch("/api/products/"+p.getId()),caller).content("{\"name\":\"QA must roll back\",\"details\":{\"weeklyAvailability\":"+invalid+"}}"),400);assertEquals(stable,read("CONS-005",label+"-invalid-day-unchanged",p,owner));}
   JsonNode clear=patchBody("CONS-005",label+"-clear-availability",p,caller,Map.of("details",Map.of("weeklyAvailability",List.of())),200);assertEquals(7,clear.path("details").path("weeklyAvailability").size());for(JsonNode day:clear.path("details").path("weeklyAvailability")){assertFalse(day.path("enabled").asBoolean());assertEquals(0,day.path("windows").size());}assertSameProduct(clear,read("CONS-005",label+"-clear-persisted",p,owner));
  }
 }
 @Test void cons007CalendarsDerivedFromOwnerNotBody()throws Exception{
