@Slf4j
@RestController
@RequestMapping("/api/products")
@Tag(name = "Products", description = "Create and manage course, download, consultation, and Membership products.")
public class ProductsController implements ProductsApiDoc {

    private final ProductService productService;
    private final ProductContentAccessService contentAccessService;

    public ProductsController(
            ProductService productService,
            ProductContentAccessService contentAccessService
    ) {
        this.productService = productService;
        this.contentAccessService = contentAccessService;
    }

    @PostMapping
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    @Override
    public ResponseEntity<AbstractProductResponseDto> createProduct(@RequestBody AbstractProductRequestDto request) {
        log.info("Received create product request: {}", request);
        AbstractProductResponseDto response = productService.createProduct(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }

    @GetMapping(params = "userId")
    @Override
    public ResponseEntity<List<AbstractProductResponseDto>> getProducts(@RequestParam(name = "userId") String userId) {
        List<AbstractProductResponseDto> response = contentAccessService.protectProductResponses(
                productService.getAllProductsForUser(userId)
        );
        return ResponseEntity.status(HttpStatus.OK).body(response);
    }

    @GetMapping(params = "ownerId")
    public ResponseEntity<List<ProductMinimised>> getProductsSummary(
            @RequestParam(name = "ownerId") String ownerId
    ) {
        List<ProductMinimised> response = productService.getProductSummariesForOwner(ownerId);
        return ResponseEntity.ok(response);
    }

    @GetMapping("/get-all-products-min")
    @Override
    public ResponseEntity<List<ProductMinimised>> getAllProductsMin(
            @RequestParam(name = "userId", required = false) String userId
    ) {
        List<ProductMinimised> response;
        if (userId != null) {
            response = productService.getAllProductsMinimisedForUser(userId);
        } else {
            response = productService.getAllProductsMinimised();
        }
        return ResponseEntity.ok(response);
    }

    @GetMapping(value = "/getProduct")
    @Override
    public ResponseEntity<AbstractProductResponseDto> getProductById(
            @RequestParam(name = "productId") String productId,
            @RequestParam(name = "type") String type) {

        AbstractProductResponseDto response = contentAccessService.protectProductResponse(
                productService.getProductByIdAndType(productId, type)
        );
        return ResponseEntity.status(HttpStatus.OK).body(response);
    }

    @GetMapping("/{productId}")
    public ResponseEntity<AbstractProductResponseDto> getProductById(
            @PathVariable("productId") String productId
    ) {
        AbstractProductResponseDto response = contentAccessService.protectProductResponse(
                productService.getProductById(productId)
        );
        return ResponseEntity.ok(response);
    }

    @PutMapping
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    @Override
    public ResponseEntity<AbstractProductResponseDto> updateProduct(@RequestBody AbstractProductRequestDto request) {
        log.info("Received update product request: {}", request.toString());
        AbstractProductResponseDto response = productService.updateProduct(request);
        return ResponseEntity.status(HttpStatus.ACCEPTED).body(response);
    }

    @PatchMapping("/{productId}")
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    public ResponseEntity<AbstractProductResponseDto> patchProduct(
            @PathVariable("productId") String productId,
            @RequestBody(required = false) com.fasterxml.jackson.databind.JsonNode request
    ) {
        AbstractProductResponseDto response = productService.patchProduct(productId, request);
        return ResponseEntity.ok(response);
    }

    @DeleteMapping()
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    @Override
    public ResponseEntity<String> deleteProduct(
            @RequestParam(name = "userId") String userId,
            @RequestParam(name = "productType") String productType,
