import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.exception.user.UserNotFoundException;
import com.myproject.video.video_platform.repository.auth.UserRepository;
import com.myproject.video.video_platform.repository.commerce.CommerceOrderRepository;
import com.myproject.video.video_platform.repository.entitlement.ProductEntitlementRepository;
import com.myproject.video.video_platform.repository.products.ProductRepository;
import com.myproject.video.video_platform.repository.products.download.DownloadProductRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipFeedEntryRepository;
import com.myproject.video.video_platform.repository.products.membership.MembershipProductRepository;
import com.myproject.video.video_platform.service.admin.AdminAuditService;
import com.myproject.video.video_platform.service.product.strategy_handler.ProductTypeHandler;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.time.Instant;
import java.util.function.Function;
import java.util.stream.Collectors;

@Slf4j
@Service
public class ProductService {

    private final UserRepository userRepository;
    private final DownloadProductRepository downloadProductRepository;
    private final DownloadProductConverter downloadProductConverter;
    private final ProductRepository productRepository;
    private final Map<ProductType, ProductTypeHandler> handlers;
    private final ProductConverter productConverter;
    private final ObjectMapper objectMapper;
    private final ProductAuthorizationService productAuthorizationService;
    private final AdminAuditService adminAuditService;
    private final ProductEntitlementRepository entitlementRepository;
    private final CommerceOrderRepository commerceOrderRepository;
    private final MembershipFeedEntryRepository membershipFeedEntryRepository;
    private final MembershipProductRepository membershipProductRepository;
    private final ProductPresentationCleanupService presentationCleanupService;
    private final ProductMediaService productMediaService;

    public ProductService(UserRepository userRepository,
                          DownloadProductRepository downloadProductRepository,
                          DownloadProductConverter downloadProductConverter,
                          ProductRepository productRepository,
                          Set<ProductTypeHandler> handlerSet,
                          ProductConverter productConverter,
                          ObjectMapper objectMapper,
                          ProductAuthorizationService productAuthorizationService,
                          AdminAuditService adminAuditService,
                          ProductEntitlementRepository entitlementRepository,
                          CommerceOrderRepository commerceOrderRepository,
                          MembershipFeedEntryRepository membershipFeedEntryRepository,
                          MembershipProductRepository membershipProductRepository,
                          ProductPresentationCleanupService presentationCleanupService,
                          ProductMediaService productMediaService) {
        this.userRepository = userRepository;
        this.downloadProductRepository = downloadProductRepository;
        this.productRepository = productRepository;
        this.downloadProductConverter = downloadProductConverter;
        this.productConverter = productConverter;
        this.objectMapper = objectMapper;
        this.productAuthorizationService = productAuthorizationService;
        this.adminAuditService = adminAuditService;
        this.entitlementRepository = entitlementRepository;
        this.commerceOrderRepository = commerceOrderRepository;
        this.membershipFeedEntryRepository = membershipFeedEntryRepository;
        this.membershipProductRepository = membershipProductRepository;
        this.presentationCleanupService = presentationCleanupService;
        this.productMediaService = productMediaService;

        // Convert the set of handlers into a map: ProductType -> handler
        this.handlers = handlerSet.stream()
                .collect(Collectors.toMap(
                        ProductTypeHandler::getSupportedType,
                        Function.identity()
                ));
    }


    public AbstractProductResponseDto createProduct(AbstractProductRequestDto dto) {
        AbstractProductResponseDto response = getProductStrategyHandler(dto.getType()).createProduct(dto);
        recordAdminProductAction("PRODUCT_CREATE", null, response);
        return enrich(response);
    }


    public AbstractProductResponseDto getProductByIdAndType(String productId, String type) {
        return enrich(getProductStrategyHandler(type).getProductById(productId));
    }

    public AbstractProductResponseDto getProductById(String productId) {
        Product product = getProductEntity(productId);
        return enrich(getProductStrategyHandler(product.getType().name()).getProductById(product.getId().toString()));
    }

    public AbstractProductResponseDto updateProduct(AbstractProductRequestDto dto) {
        Product before = getProductEntity(dto.getId());
        String beforeSummary = productSummary(before);
        AbstractProductResponseDto response = getProductStrategyHandler(dto.getType()).updateProduct(dto);
        recordAdminProductAction("PRODUCT_UPDATE", beforeSummary, response);
        return enrich(response);
    }

    public AbstractProductResponseDto patchProduct(String productId, JsonNode payload) {
        Product product = getProductEntity(productId);
        String beforeSummary = productSummary(product);
        AbstractProductRequestDto dto = mapPatchPayload(product, payload);
        AbstractProductResponseDto response = getProductStrategyHandler(product.getType().name()).updateProduct(dto);
        recordAdminProductAction("PRODUCT_UPDATE", beforeSummary, response);
        return enrich(response);
    }

    public List<AbstractProductResponseDto> getAllProductsForUser(String userId) {
        User user = userRepository.findByUserId(UUID.fromString(userId))
                .orElseThrow(() -> new UserNotFoundException("User not found with id: " + userId));

        List<Product> products = productRepository.findAllByUser(user);

        return products.stream()
                .map(product -> getProductStrategyHandler(product.getType().name())
                        .getProductById(product.getId().toString()))
                .map(this::enrich)
                .toList();
    }


    private ProductTypeHandler getProductStrategyHandler(String typeStr) {
        ProductType type;

        try {
            type = ProductType.valueOf(typeStr.toUpperCase());
        } catch (IllegalArgumentException e) {
            throw new InvalidProductTypeException("Unknown product type: " + typeStr);
        }

        ProductTypeHandler handler = handlers.get(type);
        if (handler == null) {
            throw new InvalidProductTypeException("No handler for product type: " + type);
        }
        return handler;
    }


    @Transactional
    public void deleteProduct(String userId, String productId, String productType) {
        Product before = getProductEntity(productId);
        requireProductCanBeDeleted(before.getId());
        String beforeSummary = productSummary(before);
        entitlementRepository.deleteAllByProductId(before.getId());
        removeMembershipReferences(before.getId());
        presentationCleanupService.removeProductReferences(before.getId());
        productMediaService.removeAll(before.getId());
        getProductStrategyHandler(productType).deleteProduct(userId, productId);
        recordAdminProductAction("PRODUCT_DELETE", beforeSummary, before.getId().toString(), before.getUser().getUserId().toString(), null);
    }

    @Transactional
    public void deleteProductById(String productId) {
        Product product = getProductEntity(productId);
        requireProductCanBeDeleted(product.getId());
        String beforeSummary = productSummary(product);
        entitlementRepository.deleteAllByProductId(product.getId());
        removeMembershipReferences(product.getId());
        presentationCleanupService.removeProductReferences(product.getId());
        productMediaService.removeAll(product.getId());
        getProductStrategyHandler(product.getType().name())
                .deleteProduct(product.getUser().getUserId().toString(), product.getId().toString());
        recordAdminProductAction("PRODUCT_DELETE", beforeSummary, product.getId().toString(), product.getUser().getUserId().toString(), null);
    }

    private void requireProductCanBeDeleted(UUID productId) {
        boolean hasActivePurchase = entitlementRepository.existsByProductIdAndStatusAndSource(
                productId,
                EntitlementStatus.ACTIVE,
                EntitlementSource.PURCHASE
        );
        boolean hasLiveCheckout = commerceOrderRepository.existsLivePendingOrderForProduct(
                productId,
                CommerceOrderStatus.PENDING,
                Instant.now()
        );
        if (hasActivePurchase || hasLiveCheckout) {
            throw new UnsupportedProductOperationException(
                    "Products with active purchases or checkout sessions cannot be deleted; hide the Product instead"
            );
        }
    }

    private void removeMembershipReferences(UUID productId) {
        List<UUID> membershipIds = membershipFeedEntryRepository.findMembershipIdsByIncludedProductId(productId);
        membershipFeedEntryRepository.deleteAllByIncludedProductId(productId);
        membershipIds.forEach(id -> membershipProductRepository.findById(id).ifPresent(membership -> {
            membership.setUpdatedAt(java.time.LocalDateTime.now());
            membershipProductRepository.save(membership);
        }));
    }

    private AbstractProductResponseDto enrich(AbstractProductResponseDto response) {
        if (response != null && response.getId() != null) {
            productMediaService.enrich(response.getId(), response);
        }
        return response;
    }

    public List<ProductMinimised> getAllProductsMinimised() {
        List<Product> products = productRepository.findAll();

        return products.stream()
                .map(productConverter::mapProductMinimisedToResponse)
                .toList();
    }

    public List<ProductMinimised> getAllProductsMinimisedForUser(String userId) {
        User user = userRepository.findByUserId(UUID.fromString(userId))
                .orElseThrow(() -> new UserNotFoundException("User not found: " + userId));

        List<Product> products = productRepository.findAllByUser(user);

        return products.stream()
                .map(productConverter::mapProductMinimisedToResponse)
                .toList();
    }

    public List<ProductMinimised> getProductSummariesForOwner(String ownerId) {
        return getAllProductsMinimisedForUser(ownerId);
    }

    /** EXPLORE: all products by name or owner */
    public Page<ProductMinimised> searchAllProducts(String term, Pageable pageable) {
        String normalized = term.trim().toLowerCase();
        return productRepository.searchByNameOrOwner(normalized, pageable)
                .map(productConverter::mapProductMinimisedToResponse);
    }

    /** LIBRARY/TEACHER: this user’s products by name */
    public Page<ProductMinimised> searchUserProducts(String userIdStr, String term, Pageable pageable) {
        UUID userId = UUID.fromString(userIdStr);

        userRepository.findByUserId(userId)
                .orElseThrow(() -> new UserNotFoundException("User not found: " + userIdStr));

        String normalized = term.trim().toLowerCase();
        return productRepository.searchByUserAndName(userId, normalized, pageable)
                .map(productConverter::mapProductMinimisedToResponse);
    }

    private Product getProductEntity(String productId) {
        UUID id = UUID.fromString(productId);
        return productRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Product not found: " + productId));
    }

    private void recordAdminProductAction(String action, String beforeSummary, AbstractProductResponseDto response) {
        if (!productAuthorizationService.isCurrentUserAdmin()) {
            return;
        }
        recordAdminProductAction(
                action,
                beforeSummary,
                response.getId().toString(),
                response.getUserId().toString(),
                responseSummary(response)
        );
    }

    private void recordAdminProductAction(String action,
                                          String beforeSummary,
                                          String productId,
                                          String ownerId,
                                          String afterSummary) {
        if (!productAuthorizationService.isCurrentUserAdmin()) {
            return;
        }
        adminAuditService.recordCurrentAdminAction(
                action,
                "PRODUCT",
                productId,
                beforeSummary,
                afterSummary != null ? afterSummary : "ownerId=" + ownerId
        );
    }

    private String productSummary(Product product) {
        return "id=%s,type=%s,name=%s,status=%s,ownerId=%s".formatted(
                product.getId(),
                product.getType(),
                product.getName(),
                product.getStatus(),
                product.getUser().getUserId()
        );
    }

    private String responseSummary(AbstractProductResponseDto response) {
        return "id=%s,type=%s,name=%s,status=%s,ownerId=%s".formatted(
                response.getId(),
                response.getType(),
                response.getName(),
                response.getStatus(),
                response.getUserId()
        );
    }

    private AbstractProductRequestDto mapPatchPayload(Product product, JsonNode payload) {
        ObjectNode objectNode = payload != null && payload.isObject()
                ? ((ObjectNode) payload).deepCopy()
                : objectMapper.createObjectNode();

        objectNode.put("id", product.getId().toString());
        objectNode.put("type", product.getType().name());

        if (!objectNode.hasNonNull("userId")) {
            objectNode.put("userId", product.getUser().getUserId().toString());
        }

        Class<? extends AbstractProductRequestDto> dtoClass = switch (product.getType()) {
            case COURSE -> CourseProductRequestDto.class;
            case DOWNLOAD -> DownloadProductRequestDto.class;
            case CONSULTATION -> ConsultationProductRequestDto.class;
            case MEMBERSHIP -> MembershipProductRequestDto.class;
        };

        try {
            AbstractProductRequestDto dto = objectMapper.treeToValue(objectNode, dtoClass);
            if (dto instanceof DownloadProductRequestDto downloadDto) {
                downloadDto.setDetails(null);
            }
            if (dto instanceof CourseProductRequestDto courseDto) {
                courseDto.setDetails(null);
            }
            return dto;
        } catch (JsonProcessingException e) {
            throw new InvalidProductTypeException("Invalid product patch payload: " + e.getOriginalMessage());
        }
    }
}

package com.myproject.video.video_platform.common.converter.product;

import com.myproject.video.video_platform.common.enums.products.ProductStatus;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.consultation.ConsultationProductDetailsDto;
import com.myproject.video.video_platform.dto.products.consultation.ConsultationProductRequestDto;
import com.myproject.video.video_platform.dto.products.consultation.ConsultationProductResponseDto;
import com.myproject.video.video_platform.entity.products.consultation.ConnectedCalendar;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationAvailabilityDay;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationAvailabilityWindow;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationProduct;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.repository.products.consultation.ConnectedCalendarRepository;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

@Component
public class ConsultationProductConverter {

    private final ConnectedCalendarRepository calendarRepository;
    private static final ProductStatus DEFAULT_STATUS = ProductStatus.DRAFT;

    public ConsultationProductConverter(ConnectedCalendarRepository calendarRepository) {
        this.calendarRepository = calendarRepository;
    }

    /**
     * Map incoming DTO + user → JPA entity.
     */
    public ConsultationProduct fromDto(ConsultationProductRequestDto dto, User user) {
        ConsultationProduct entity = new ConsultationProduct();
        entity.setName(dto.getName());
        entity.setDescription(dto.getDescription());
        entity.setStatus(parseStatus(dto.getStatus(), DEFAULT_STATUS));
        entity.setPrice(parsePrice(dto.getPrice(), BigDecimal.ZERO));
        ProductPricingSupport.initializeOneTime(entity);
        entity.setType(ProductType.CONSULTATION);
        entity.setUser(user);

        ConsultationProductDetailsDto details = dto.getDetails();
        if (details != null) {
            entity.setDurationMinutes(details.getDurationMinutes());
            entity.setMeetingMethod(details.getMeetingMethod() != null
                    ? ConsultationProduct.MeetingMethod.valueOf(details.getMeetingMethod().name())
                    : null);
            entity.setCustomLocation(details.getCustomLocation());
            entity.setBufferBeforeMinutes(details.getBufferBeforeMinutes());
            entity.setBufferAfterMinutes(details.getBufferAfterMinutes());
            entity.setMaxSessionsPerDay(details.getMaxSessionsPerDay());
            entity.setConfirmationMessage(details.getConfirmationMessage());
            entity.setCancellationPolicy(details.getCancellationPolicy());
            applyAvailability(entity, details.getWeeklyAvailability());
        }

        return entity;
    }

    /**
     * Map JPA entity → outgoing DTO.
     */
    public ConsultationProductResponseDto toDto(ConsultationProduct entity) {
        List<ConnectedCalendar> calendars = calendarRepository.findAllByTeacherId((entity.getUser().getUserId()));

        ConsultationProductResponseDto dto = new ConsultationProductResponseDto();
        dto.setId(entity.getId());
        dto.setName(entity.getName());
        dto.setDescription(entity.getDescription());
        dto.setStatus(entity.getStatus() != null ? entity.getStatus().name() : DEFAULT_STATUS.name());
        dto.setPrice(entity.getPrice() == null
                ? "0"
                : entity.getPrice().compareTo(BigDecimal.ZERO) == 0
                ? "free"
                : entity.getPrice().toString());
        dto.setType(entity.getType() != null ? entity.getType().name() : ProductType.CONSULTATION.name());
        dto.setUserId(entity.getUser().getUserId());
        dto.setCreatedAt(entity.getCreatedAt());
        dto.setUpdatedAt(entity.getUpdatedAt() != null ? entity.getUpdatedAt() : entity.getCreatedAt());
        ProductPricingSupport.mapResponse(entity, dto);

        ConsultationProductDetailsDto details = new ConsultationProductDetailsDto();
        details.setDurationMinutes(entity.getDurationMinutes());
        details.setMeetingMethod(entity.getMeetingMethod() != null
                ? ConsultationProductDetailsDto.MeetingMethod.valueOf(entity.getMeetingMethod().name())
                : null);
        details.setCustomLocation(entity.getCustomLocation());
        details.setBufferBeforeMinutes(entity.getBufferBeforeMinutes());
        details.setBufferAfterMinutes(entity.getBufferAfterMinutes());
        details.setMaxSessionsPerDay(entity.getMaxSessionsPerDay());
        details.setConfirmationMessage(entity.getConfirmationMessage());
        details.setCancellationPolicy(entity.getCancellationPolicy());
        details.setConnectedCalendars(
                calendars.stream()
                        .map(this::toCalendarDto)
                        .collect(Collectors.toList())
        );
        details.setWeeklyAvailability(toAvailabilityDto(entity));

        dto.setDetails(details);
        return dto;
    }

    /**
     * Update an existing entity with fields from DTO.
     */
    public void updateEntityFromDto(ConsultationProductRequestDto dto, ConsultationProduct entity) {
        if (dto.getName() != null) {
            entity.setName(dto.getName());
        }
        if (dto.getDescription() != null) {
            entity.setDescription(dto.getDescription());
        }
        if (dto.getStatus() != null) {
            entity.setStatus(parseStatus(dto.getStatus(), entity.getStatus() != null ? entity.getStatus() : DEFAULT_STATUS));
        }
        if (dto.getPrice() != null) {
            entity.setPrice(parsePrice(dto.getPrice(), entity.getPrice() != null ? entity.getPrice() : BigDecimal.ZERO));
        }

        ConsultationProductDetailsDto details = dto.getDetails();
        if (details == null) {
            return;
        }

        if (details.getDurationMinutes() != null) {
            entity.setDurationMinutes(details.getDurationMinutes());
        }
        if (details.getMeetingMethod() != null) {
            entity.setMeetingMethod(ConsultationProduct.MeetingMethod.valueOf(details.getMeetingMethod().name()));
        }
        if (details.getCustomLocation() != null) {
            entity.setCustomLocation(details.getCustomLocation());
        }
        if (details.getBufferBeforeMinutes() != null) {
            entity.setBufferBeforeMinutes(details.getBufferBeforeMinutes());
        }
        if (details.getBufferAfterMinutes() != null) {
            entity.setBufferAfterMinutes(details.getBufferAfterMinutes());
        }
        if (details.getMaxSessionsPerDay() != null) {
            entity.setMaxSessionsPerDay(details.getMaxSessionsPerDay());
        }
        if (details.getConfirmationMessage() != null) {
            entity.setConfirmationMessage(details.getConfirmationMessage());
        }
        if (details.getCancellationPolicy() != null) {
            entity.setCancellationPolicy(details.getCancellationPolicy());
        }
        if (details.getWeeklyAvailability() != null) {
            applyAvailability(entity, details.getWeeklyAvailability());
        }
    }

    private void applyAvailability(ConsultationProduct entity,
                                   List<ConsultationProductDetailsDto.AvailabilityDayDto> requested) {
        if (requested == null) return;
        Set<ConsultationProductDetailsDto.Weekday> seen = new HashSet<>();
        List<ConsultationAvailabilityDay> replacement = new java.util.ArrayList<>();
        for (ConsultationProductDetailsDto.AvailabilityDayDto source : requested) {
            if (source == null || source.getDay() == null || !seen.add(source.getDay())) {
                throw new IllegalArgumentException("Weekly availability contains a missing or duplicate weekday");
            }
            ConsultationAvailabilityDay day = new ConsultationAvailabilityDay();
            day.setConsultation(entity);
            day.setWeekday(ConsultationAvailabilityDay.Weekday.valueOf(source.getDay().name()));
            day.setEnabled(Boolean.TRUE.equals(source.getEnabled()));
            List<ConsultationProductDetailsDto.AvailabilityWindowDto> slots = source.getWindows() == null
                    ? List.of() : source.getWindows();
            int position = 0;
            for (ConsultationProductDetailsDto.AvailabilityWindowDto slot : slots) {
                try {
                    ConsultationAvailabilityWindow window = new ConsultationAvailabilityWindow();
                    window.setDay(day);
                    window.setStartTime(LocalTime.parse(slot.getStartTime(), DateTimeFormatter.ofPattern("HH:mm")));
                    window.setEndTime(LocalTime.parse(slot.getEndTime(), DateTimeFormatter.ofPattern("HH:mm")));
                    window.setPosition(position++);
                    day.getWindows().add(window);
                } catch (NullPointerException | DateTimeParseException ex) {
                    throw new IllegalArgumentException("Weekly availability times must use HH:mm syntax");
                }
            }
            replacement.add(day);
        }
        entity.getWeeklyAvailability().clear();
        entity.getWeeklyAvailability().addAll(replacement);
    }

    private List<ConsultationProductDetailsDto.AvailabilityDayDto> toAvailabilityDto(ConsultationProduct entity) {
        Map<ConsultationAvailabilityDay.Weekday, ConsultationAvailabilityDay> persisted =
                new EnumMap<>(ConsultationAvailabilityDay.Weekday.class);
        entity.getWeeklyAvailability().forEach(day -> persisted.put(day.getWeekday(), day));
        return java.util.Arrays.stream(ConsultationAvailabilityDay.Weekday.values()).map(weekday -> {
            ConsultationAvailabilityDay day = persisted.get(weekday);
            ConsultationProductDetailsDto.AvailabilityDayDto dto = new ConsultationProductDetailsDto.AvailabilityDayDto();
            dto.setDay(ConsultationProductDetailsDto.Weekday.valueOf(weekday.name()));
            dto.setEnabled(day != null && day.isEnabled());
            dto.setWindows(day == null ? List.of() : day.getWindows().stream().map(window -> {
                ConsultationProductDetailsDto.AvailabilityWindowDto slot = new ConsultationProductDetailsDto.AvailabilityWindowDto();
                slot.setStartTime(window.getStartTime().format(DateTimeFormatter.ofPattern("HH:mm")));
                slot.setEndTime(window.getEndTime().format(DateTimeFormatter.ofPattern("HH:mm")));
                return slot;
            }).toList());
            return dto;
        }).toList();
    }

    private ConsultationProductDetailsDto.ConnectedCalendarDto toCalendarDto(ConnectedCalendar cal) {
        ConsultationProductDetailsDto.ConnectedCalendarDto c = new ConsultationProductDetailsDto.ConnectedCalendarDto();
        c.setId(cal.getId().toString());
        c.setProvider(cal.getProvider().name());
        c.setExpiresAt(cal.getExpiresAt().toString());
        return c;
    }

    private ProductStatus parseStatus(String statusStr, ProductStatus fallback) {
        if (statusStr == null || statusStr.isBlank()) {
            return fallback;
        }
        try {
            return ProductStatus.valueOf(statusStr.toUpperCase());
        } catch (IllegalArgumentException e) {
            return fallback;
        }
    }

    private BigDecimal parsePrice(String priceStr, BigDecimal fallback) {
        if (priceStr == null || priceStr.isBlank()) {
            return fallback;
        }
        if (priceStr.equalsIgnoreCase("free")) {
            return BigDecimal.ZERO;
        }
        try {
            return new BigDecimal(priceStr);
        } catch (NumberFormatException e) {
            return fallback;
        }
    }
}

package com.myproject.video.video_platform.dto.products.consultation;

import com.fasterxml.jackson.annotation.JsonCreator;
import io.swagger.v3.oas.annotations.media.Schema;
import lombok.Data;

import java.util.List;
import java.util.Locale;

@Data
@Schema(description = "Consultation-specific fields nested under product.details.")
public class ConsultationProductDetailsDto {

    @Schema(description = "Duration in minutes", example = "60")
    private Integer durationMinutes;

    @Schema(description = "Meeting delivery method", example = "ZOOM")
    private MeetingMethod meetingMethod;

    @Schema(description = "Optional custom meeting location", example = "https://cal.example.com/room/amelia")
    private String customLocation;

    @Schema(description = "Buffer before the session in minutes", example = "10")
    private Integer bufferBeforeMinutes;

    @Schema(description = "Buffer after the session in minutes", example = "10")
    private Integer bufferAfterMinutes;

    @Schema(description = "Maximum number of sessions per day", example = "5")
    private Integer maxSessionsPerDay;

    @Schema(description = "Message sent after booking")
    private String confirmationMessage;

    @Schema(description = "Cancellation policy presented to learners")
    private String cancellationPolicy;

    @Schema(description = "Calendars currently linked for real-time availability")
    private List<ConnectedCalendarDto> connectedCalendars;

    @Schema(description = "Weekly bookable hours. Omit on update to preserve existing availability; send [] to clear it.")
    private List<AvailabilityDayDto> weeklyAvailability;

    @Data
    public static class AvailabilityDayDto {
        private Weekday day;
        private Boolean enabled;
        private List<AvailabilityWindowDto> windows;
    }

    @Data
    public static class AvailabilityWindowDto {
        @Schema(example = "09:00")
        private String startTime;
        @Schema(example = "17:00")
        private String endTime;
    }

    public enum Weekday {
        MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY, SATURDAY, SUNDAY
    }

    @Data
    @Schema(description = "Connected calendar integration summary.")
    public static class ConnectedCalendarDto {
        @Schema(description = "Calendar identifier", example = "e10f1e98-5a1d-4d1b-83ff-2be4a708f542")
        private String id;
        @Schema(description = "Calendar provider", example = "GOOGLE")
        private String provider;
        @Schema(description = "Token expiry timestamp", example = "2024-05-01T10:00:00Z")
        private String expiresAt;
    }

    public enum MeetingMethod {
        ZOOM,
        GOOGLE_MEET,
        PHONE,
        OTHER;

        @JsonCreator
        public static MeetingMethod fromJson(String value) {
            if (value == null || value.isBlank()) {
                return null;
            }

            String normalized = value.trim()
                    .toUpperCase(Locale.ROOT)
                    .replace('-', '_')
                    .replace(' ', '_');

            return switch (normalized) {
                case "ZOOM", "ZOOM_MEETING" -> ZOOM;
                case "GOOGLE", "GOOGLE_MEET", "GOOGLE_MEETING" -> GOOGLE_MEET;
                case "PHONE", "PHONE_CALL", "CALL", "TELEPHONE" -> PHONE;
                case "OTHER", "CUSTOM" -> OTHER;
                default -> throw new IllegalArgumentException("Unknown meetingMethod: " + value);
            };
        }

    }
}

