 @Autowired @Qualifier("requestMappingHandlerMapping") RequestMappingHandlerMapping handlers;
 @AfterAll static void confirmCleanup(@Autowired org.springframework.jdbc.core.JdbcTemplate j){Map<String,Long> counts=new LinkedHashMap<>();for(String t:List.of("users","roles","user_roles","verification_tokens","course_products","download_products","consultation_products","membership_products","consultation_availability_days","consultation_availability_windows","admin_audit_logs","commerce_orders","commerce_order_items","commerce_payment_attempts","commerce_payment_events","product_entitlements")){Long n=j.queryForObject("SELECT count(*) FROM "+t,Long.class);counts.put(t,n);assertEquals(0L,n,t+" cleanup");}observations.add(Map.of("kind","final-cleanup","table_counts",counts));}
 void unavailable(String c,String label,MockHttpServletRequestBuilder req)throws Exception{
  var res=mvc.perform(req).andReturn();int status=res.getResponse().getStatus();Object h=res.getHandler();String txt=res.getResponse().getContentAsString();JsonNode body=txt.isEmpty()?mapper.nullNode():mapper.readTree(txt);
  boolean staticAbsent=body.path("message").asText().contains("No static resource");
  Map<String,Object> row=new LinkedHashMap<>();row.put("case_id",c);row.put("label",label);row.put("actual_status",status);row.put("handler_class",h==null?"none":h.getClass().getSimpleName());row.put("controller_handler",h instanceof HandlerMethod);row.put("static_resource_absent_message",staticAbsent);row.put("resolved_exception",res.getResolvedException()==null?"none":res.getResolvedException().getClass().getSimpleName());row.put("observed_at",java.time.Instant.now().toString());observations.add(row);
  assertFalse(h instanceof HandlerMethod,"No implemented controller for client-only path");assertTrue(status>=400&&status<500,"Unsupported request returns client error");assertFalse(body.has("token"));assertFalse(body.has("resetToken"));
  for(Cookie cookie:res.getResponse().getCookies())assertFalse(Set.of("JWT_TOKEN","REFRESH_TOKEN").contains(cookie.getName()),"Unavailable request does not issue authentication");
 }
 Map<UUID,String> passwords(){Map<UUID,String> p=new HashMap<>();for(User u:users.findAll())p.put(u.getUserId(),u.getPassword());return p;}
 @Test void auth017RawStringForgotNoRecovery()throws Exception{
  User target=extra("forgot-target",buyer);Map<UUID,String> before=passwords();long verificationBefore=jdbc.queryForObject("select count(*) from verification_tokens",Long.class);
  assertTrue(handlers.getHandlerMethods().keySet().stream().flatMap(x->x.getPatternValues().stream()).noneMatch(x->x.contains("forgot")||x.contains("reset")));
  for(User actor:Arrays.asList(null,buyer,owner,admin))for(String email:List.of(target.getEmail(),"missing-forgot@example.invalid")){
   var req=post("/api/auth/forgot").contentType(MediaType.APPLICATION_JSON).cookie(new Cookie("XSRF-TOKEN","qa-isolated-csrf")).header("X-XSRF-TOKEN","qa-isolated-csrf").content(mapper.writeValueAsString(email));if(actor!=null)req.cookie(auth(actor));
   unavailable("AUTH-017",(actor==null?"Guest":role(actor))+"-"+(email.equals(target.getEmail())?"existing":"unknown")+"-raw-json-string",req);
   assertEquals(before,passwords());assertEquals(verificationBefore,jdbc.queryForObject("select count(*) from verification_tokens",Long.class));noFinancialRecords();
  }
 }
 @Test void local008ActualReviewClientPathsAndShapes()throws Exception{
  Product p=seed(ProductType.COURSE,owner,"10",ProductStatus.DRAFT);UUID review=UUID.randomUUID();JsonNode before=read("LOCAL-008","product-before",p,owner);
  assertTrue(handlers.getHandlerMethods().keySet().stream().flatMap(x->x.getPatternValues().stream()).noneMatch(x->x.contains("review")));
  for(User actor:List.of(owner,buyer,admin)){
   Map<String,Object> creation=Map.of("productId",p.getId().toString(),"userId",actor.getUserId().toString(),"rating",5,"comment","QA synthetic review","hidden",false);Map<String,Object> edit=new LinkedHashMap<>(creation);edit.put("id",review.toString());Map<String,Object> reply=Map.of("authorId",actor.getUserId().toString(),"comment","QA synthetic reply","createdAt","2026-10-04T00:00:00Z","updatedAt","2026-10-04T00:00:00Z");String base="/api/review/"+review;
   List<MockHttpServletRequestBuilder> requests=List.of(
    mutation(post("/api/products/"+p.getId()+"/review"),actor).content(mapper.writeValueAsString(creation)),
    mutation(patch(base),actor).content(mapper.writeValueAsString(edit)),
    mutation(delete("/api/reviews/"+review),actor),
    get("/api/creators/reviews").param("productId",p.getId().toString()).param("rating","").param("status","").param("search","").param("page","0").param("size","20").cookie(auth(actor)),
    mutation(put(base+"/visibility"),actor).content("true"),
    mutation(post(base+"/reply"),actor).content(mapper.writeValueAsString(reply)),
    mutation(put(base+"/reply"),actor).content(mapper.writeValueAsString(reply)),
    mutation(delete(base+"/reply"),actor));
   List<String> labels=List.of("create-review","patch-review","delete-review","list-reviews","boolean-visibility","create-reply","update-reply","delete-reply");
   for(int i=0;i<requests.size();i++){unavailable("LOCAL-008",role(actor)+"-"+labels.get(i),requests.get(i));assertEquals(before,read("LOCAL-008",role(actor)+"-unchanged-after-"+labels.get(i),p,owner));assertEquals(1,products.count());assertEquals(0,audits.count());noFinancialRecords();}
  }
  assertEquals(0L,jdbc.queryForObject("select count(*) from information_schema.tables where lower(table_name) like '%review%'",Long.class));
 }
 @Test void prod024BlankCourseNamesRejectAndRepair()throws Exception{
  for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN))for(String name:Arrays.asList(null,"","   ","\t\n")){
   String label=role(caller)+"-"+state+"-"+(name==null?"null":name.isEmpty()?"empty":name.contains("\t")?"tabs-newlines":"spaces");Product p=seed(ProductType.COURSE,owner,"10",state);readyArticle(p);p.setName(name);products.saveAndFlush(p);JsonNode before=read("PROD-024",label+"-before",p,owner);
   JsonNode rejected=patchBody("PROD-024",label+"-publish",p,caller,Map.of("status","PUBLISHED"),422);assertEquals(1,rejected.path("errors").size());assertEquals("Name is required",rejected.path("errors").path("name").asText());assertEquals(before,read("PROD-024",label+"-atomic-rollback",p,owner));assertEquals(state,products.findById(p.getId()).orElseThrow().getStatus());
   JsonNode accepted=patchBody("PROD-024",label+"-corrected-name-and-publish",p,caller,Map.of("name","QA corrected Course title","status","PUBLISHED"),200);assertEquals("PUBLISHED",accepted.path("status").asText());assertEquals("QA corrected Course title",accepted.path("name").asText());assertSameProduct(accepted,read("PROD-024",label+"-readback",p,owner));
  }
 }
 @Test void prod025DownloadDeliverableRejectionApiOnly()throws Exception{
  for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN))for(String path:List.of("absent","null","empty","spaces")){
   String label=role(caller)+"-"+state+"-path-"+path;Product p=seed(ProductType.DOWNLOAD,owner,"10",state);FileDownloadProduct f=null;if(!path.equals("absent")){f=downloadFile(p);f.setPath(path.equals("null")?null:path.equals("empty")?"":"   ");files.saveAndFlush(f);}JsonNode before=read("PROD-025",label+"-before",p,owner);
   if(f!=null){assertEquals(f.getId().toString(),before.path("details").path("sections").get(0).path("files").get(0).path("id").asText());assertEquals("qa-synthetic.zip",before.path("details").path("sections").get(0).path("files").get(0).path("fileName").asText());}
   JsonNode rejected=patchBody("PROD-025",label+"-publish",p,caller,Map.of("status","PUBLISHED"),422);assertEquals(1,rejected.path("errors").size());assertEquals("At least one confirmed file is required",rejected.path("errors").path("details.files").asText());assertEquals(before,read("PROD-025",label+"-rollback",p,owner));assertEquals(state,products.findById(p.getId()).orElseThrow().getStatus());
   if(f==null)f=downloadFile(p);else{f.setPath("qa-metadata-only/ready.zip");files.saveAndFlush(f);}JsonNode accepted=patchBody("PROD-025",label+"-confirmed-path-control",p,caller,Map.of("status","PUBLISHED"),200);assertEquals("PUBLISHED",accepted.path("status").asText());assertSameProduct(accepted,read("PROD-025",label+"-control-readback",p,owner));assertEquals(0,files.findById(f.getId()).orElseThrow().getDownloadCount());
  }
 }
 Map<String,Object> readyConsultation(){return Map.of("durationMinutes",30,"meetingMethod","ZOOM","weeklyAvailability",List.of(availability(true,false)));}
 Product ready(String c,String label,ProductType t,ProductStatus state,User actor)throws Exception{
  if(t==ProductType.CONSULTATION){Map<String,Object> b=payload(t,owner);b.put("status",state.name());b.put("price","10");b.put("details",readyConsultation());return entity(create(c,label+"-create",actor,b,201));}
  Product p=seed(t,owner,"10",state);if(t==ProductType.COURSE)readyArticle(p);if(t==ProductType.DOWNLOAD)downloadFile(p);return p;
 }
 @Test void prod026MalformedTimeRollbackAndExistingWeekdayRetry()throws Exception{
  int validRetryFailures=0;
  for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN))for(String bad:List.of("garbage","9:00","25:00","09:60","09:00:00",""))for(String field:List.of("startTime","endTime")){
   String label=role(caller)+"-"+state+"-"+field+"-"+(bad.isEmpty()?"empty":bad);Product p=ready("PROD-026",label,ProductType.CONSULTATION,state,caller);JsonNode before=read("PROD-026",label+"-before",p,owner);Map<String,Object> window=new LinkedHashMap<>(Map.of("startTime","09:00","endTime","12:00"));window.put(field,bad);
   Map<String,Object> details=Map.of("durationMinutes",99,"weeklyAvailability",List.of(Map.of("day","MONDAY","enabled",true,"windows",List.of(window))));
   JsonNode rejected=patchBody("PROD-026",label+"-malformed-publish",p,caller,Map.of("name","QA must roll back","details",details,"status","PUBLISHED"),400);assertTrue(rejected.path("message").asText().contains("HH:mm"));assertEquals(before,read("PROD-026",label+"-malformed-atomic-rollback",p,owner));assertEquals(state,products.findById(p.getId()).orElseThrow().getStatus());
   var response=mvc.perform(mutation(patch("/api/products/"+p.getId()),caller).content(mapper.writeValueAsString(Map.of("details",Map.of("weeklyAvailability",List.of(availability(true,false))),"status","PUBLISHED")))).andReturn();int status=response.getResponse().getStatus();JsonNode body=mapper.readTree(response.getResponse().getContentAsString());String msg=body.path("message").asText().toLowerCase();boolean unique=msg.contains("unique")&&msg.contains("consultation_availability_days");observations.add(Map.of("case_id","PROD-026","label",label+"-valid-retry","actual_status",status,"expected_status",200,"availability_unique_constraint_error",unique,"observed_at",java.time.Instant.now().toString()));
   if(status!=200){validRetryFailures++;assertEquals(400,status);assertTrue(unique);assertEquals(before,read("PROD-026",label+"-valid-retry-rollback",p,owner));patchBody("PROD-026",label+"-clear-days-workaround",p,caller,Map.of("details",Map.of("weeklyAvailability",List.of())),200);JsonNode accepted=patchBody("PROD-026",label+"-valid-retry-after-clear",p,caller,Map.of("details",Map.of("weeklyAvailability",List.of(availability(true,false))),"status","PUBLISHED"),200);assertEquals("PUBLISHED",accepted.path("status").asText());assertEquals(30,accepted.path("details").path("durationMinutes").asInt());assertEquals(before.path("name"),accepted.path("name"));assertSameProduct(accepted,read("PROD-026",label+"-workaround-readback",p,owner));}else assertSameProduct(body,read("PROD-026",label+"-successful-retry-readback",p,owner));
  }
  assertEquals(0,validRetryFailures,"Corrected weekly times should save and publish without clearing existing weekdays");
 }
 Set<String> storefrontProducts(JsonNode n){Set<String>s=new HashSet<>();n.path("products").forEach(x->s.add(x.path("id").asText()));return s;}
 @Test void prod029HideManageDenyGuestKeepEntitlementAndRestore()throws Exception{
  for(User caller:List.of(owner,admin))for(ProductType type:ProductType.values()){
   String label=role(caller)+"-"+type;Product p=ready("PROD-029",label,type,ProductStatus.DRAFT,caller);
   if(type!=ProductType.MEMBERSHIP){JsonNode pub=patchBody("PROD-029",label+"-initial-supported-publication",p,caller,Map.of("status","PUBLISHED"),200);assertEquals("PUBLISHED",pub.path("status").asText());grant(p,buyer,EntitlementSource.ADMIN_GRANT,EntitlementStatus.ACTIVE);assertTrue(storefrontProducts(perform("PROD-029",label+"-public-before",get("/api/storefronts/"+owner.getUserId()),200)).contains(p.getId().toString()));}
   JsonNode hidden=patchBody("PROD-029",label+"-hide",p,caller,Map.of("status","HIDDEN"),200);assertEquals("HIDDEN",hidden.path("status").asText());assertEquals(ProductStatus.HIDDEN,products.findById(p.getId()).orElseThrow().getStatus());assertSameProduct(hidden,read("PROD-029",label+"-owner-manages-hidden",p,owner));assertSameProduct(hidden,read("PROD-029",label+"-admin-manages-hidden",p,admin));
   perform("PROD-029",label+"-guest-hidden-denied",get("/api/products/"+p.getId()),403);perform("PROD-029",label+"-unentitled-hidden-denied",get("/api/products/"+p.getId()).cookie(auth(extra("unentitled-"+label.replace(' ','-'),buyer))),403);
   assertFalse(storefrontProducts(perform("PROD-029",label+"-storefront-excludes-hidden",get("/api/storefronts/"+owner.getUserId()),200)).contains(p.getId().toString()));
   JsonNode managed=perform("PROD-029",label+"-owner-management-list",get("/api/products").param("userId",owner.getUserId().toString()).cookie(auth(owner)),200);assertTrue(java.util.stream.StreamSupport.stream(managed.spliterator(),false).anyMatch(x->x.path("id").asText().equals(p.getId().toString())&&x.path("status").asText().equals("HIDDEN")));
   if(type==ProductType.MEMBERSHIP){patchBody("PROD-029",label+"-membership-publication-unsupported",p,caller,Map.of("status","PUBLISHED"),409);assertSameProduct(hidden,read("PROD-029",label+"-unsupported-rollback",p,owner));assertTrue(grants.findByUserUserIdAndProductId(buyer.getUserId(),p.getId()).isEmpty());}
   else{JsonNode holder=read("PROD-029",label+"-active-holder-hidden-read",p,buyer);assertEquals("HIDDEN",holder.path("status").asText());if(type==ProductType.COURSE)assertTrue(holder.toString().contains("QA ready article"));assertTrue(libraryIds("PROD-029").contains(p.getId()));access("PROD-029",p,true);assertEquals(EntitlementStatus.ACTIVE,grants.findByUserUserIdAndProductId(buyer.getUserId(),p.getId()).orElseThrow().getStatus());JsonNode restored=patchBody("PROD-029",label+"-restore-supported-publication",p,caller,Map.of("status","PUBLISHED"),200);assertEquals("PUBLISHED",restored.path("status").asText());assertEquals("PUBLISHED",read("PROD-029",label+"-guest-restored-read",p,null).path("status").asText());assertTrue(storefrontProducts(perform("PROD-029",label+"-storefront-restored",get("/api/storefronts/"+owner.getUserId()),200)).contains(p.getId().toString()));}
  }
  assertEquals(6,grants.count());assertEquals(0,orders.count());assertEquals(0,attempts.count());assertEquals(0,events.count());
 }
}

