 @Test void papi011InvalidCreatePutAndProductIdsNoMutation()throws Exception{
  Product control=seed(ProductType.COURSE,owner,"10",ProductStatus.DRAFT);courseContent(control);JsonNode before=read("PAPI-011","control-before",control,owner);
  for(User actor:List.of(owner,admin)){
   for(String type:List.of("missing","null","unsupported","lowercase","integer","object"))for(String method:List.of("POST","PUT")){
    Map<String,Object>b=new LinkedHashMap<>();b.put("id",control.getId().toString());b.put("userId",owner.getUserId().toString());b.put("name","QA rejected mutation");b.put("price","99");switch(type){case"null"->b.put("type",null);case"unsupported"->b.put("type","UNSUPPORTED");case"lowercase"->b.put("type","course");case"integer"->b.put("type",12);case"object"->b.put("type",Map.of());}
    var req=method.equals("POST")?post("/api/products"):put("/api/products");perform("PAPI-011",label(actor)+"-"+method+"-type-"+type,mutation(req,actor).content(mapper.writeValueAsString(b)),400);noControlMutation("PAPI-011",label(actor)+method+type,control,before);
   }
   for(String variant:List.of("missing","null","malformed","unknown"))for(ProductType type:ProductType.values()){
    Map<String,Object>b=payload(type,owner);if(variant.equals("null"))b.put("id",null);else if(!variant.equals("missing"))b.put("id",variant.equals("malformed")?"not-a-uuid":UUID.randomUUID().toString());perform("PAPI-011",label(actor)+"-PUT-"+type+"-id-"+variant,mutation(put("/api/products"),actor).content(mapper.writeValueAsString(b)),variant.equals("unknown")?404:400);noControlMutation("PAPI-011",label(actor)+type+variant,control,before);
   }
   for(String id:List.of("not-a-uuid",UUID.randomUUID().toString())){
    int expected=id.equals("not-a-uuid")?400:404;
    perform("PAPI-011",label(actor)+"-canonical-GET-"+expected,get("/api/products/"+id).cookie(auth(actor)),expected);
    perform("PAPI-011",label(actor)+"-canonical-PATCH-"+expected,mutation(patch("/api/products/"+id),actor).content("{\"name\":\"QA rejected\"}"),expected);
    perform("PAPI-011",label(actor)+"-canonical-DELETE-"+expected,mutation(delete("/api/products/"+id),actor),expected);
    for(ProductType type:ProductType.values()){perform("PAPI-011",label(actor)+"-typed-GET-"+type+"-"+expected,get("/api/products/getProduct").param("productId",id).param("type",type.name()).cookie(auth(actor)),expected);perform("PAPI-011",label(actor)+"-legacy-DELETE-"+type+"-"+expected,mutation(delete("/api/products"),actor).param("userId",owner.getUserId().toString()).param("productType",type.name()).param("id",id),expected);}
    noControlMutation("PAPI-011",label(actor)+expected,control,before);
   }
  }
 }
